public void Save(string path) {
    string full = Path.GetFullPath(path), directory = Path.GetDirectoryName(full)!;
    var prepared=PrepareSave?.Invoke(Copy(document),BaseDirectory)??document;
    var rebased = Rebase(prepared, BaseDirectory, directory);
    SolutionStore.Save(full, rebased); // Commit editor state only after an atomic successful write.
    document = rebased; BaseDirectory = directory; FilePath = full; IsDirty = false; Revision++; Changed?.Invoke();
}

public SolutionDocument PrepareSave(SolutionDocument document,string baseDirectory,ModuleExecutionScope? scope){
 var catalog=new ResourceCatalog(baseDirectory,document.Resources);var resources=document.Resources.Where(r=>!plugins.Values.Any(p=>p is IToolAssetPersistence&&r.Id.StartsWith("plugin:"+p.Manifest.Id+":",StringComparison.Ordinal))).ToDictionary(r=>r.Id,StringComparer.Ordinal);
 var procedures=document.Procedures.Select(procedure=>procedure with{Nodes=procedure.Nodes.Select(node=>{
  if(Find(node.ModuleId) is not IToolAssetPersistence participant)return node;
  var snapshot=participant.PrepareSave(node,baseDirectory,catalog,scope?.ForProcedure(procedure.Id));foreach(var resource in snapshot.Resources)resources[resource.Id]=resource;return snapshot.Node;
 }).ToArray()}).ToArray();return document with{Procedures=procedures,Resources=resources.Values.ToArray()};
}

public static void Save(string path,SolutionDocument solution) {
    ValidateStructure(solution);byte[] json=JsonSerializer.SerializeToUtf8Bytes(solution,Options);if(json.Length>MaximumBytes)throw new InvalidDataException("Solution exceeds size limit.");
    // Opaque plugin payloads can contain duplicate members. Reject the same
    // serialized shape as Load before creating directories or replacing a file.
    using(var parsed=JsonDocument.Parse(json))RejectDuplicateProperties(parsed.RootElement);
    string full=Path.GetFullPath(path),directory=Path.GetDirectoryName(full)!;Directory.CreateDirectory(directory);string temp=Path.Combine(directory,"."+Path.GetFileName(full)+"."+Guid.NewGuid().ToString("N")+".tmp");
    try{using(var output=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){output.Write(json);output.Flush(true);}File.Move(temp,full,overwrite:true);}finally{if(File.Exists(temp))File.Delete(temp);}
}
